<?php
if(!$PCC->tableExists('rp_characters')):?><section class="pcc-panel"><div class="pcc-empty"><i class="fas fa-id-badge"></i><strong>Character V2 indisponible</strong><span>rp_characters n’existe pas.</span></div></section><?php return;endif;
$q=trim((string)($_GET['q']??''));$where='1=1';$types='';$params=array();if($q!==''){$like='%'.mb_substr($q,0,64).'%';$where='(u.username LIKE ? OR c.citizen_id LIKE ? OR CONCAT(c.first_name,\' \',c.last_name) LIKE ?)';$types='sss';$params=array($like,$like,$like);}$rows=$DB->PreparedAll('SELECT c.*,u.username,u.look,u.rank,u.online,u.account_created FROM rp_characters c INNER JOIN users u ON u.id=c.user_id WHERE '.$where.' ORDER BY c.id DESC LIMIT 500',$types,$params);
?>
<section class="pcc-panel"><form class="pcc-filterbar"><input type="hidden" name="page" value="characters"><div class="pcc-search-field"><i class="fas fa-search"></i><input name="q" value="<?php echo $h($q);?>" placeholder="Username, nom RP ou Citizen ID…"></div><button class="pcc-button secondary">Rechercher</button><span class="pcc-filter-count"><?php echo $number(count($rows));?> personnage(s)</span></form><div class="pcc-table-wrap"><table class="pcc-table"><thead><tr><th>Joueur</th><th>Nom RP</th><th>Citizen ID</th><th>Naissance</th><th>Genre</th><th>Nationalité</th><th>Réputation</th><th>Créé</th><th>Statut</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="10"><div class="pcc-empty compact"><strong>Aucun personnage trouvé</strong></div></td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><div class="pcc-user-cell"><img class="pcc-table-avatar" src="<?php echo $h($PCC->avatarUrl($r['look'],'s'));?>" alt=""><span><strong><?php echo $h($r['username']);?></strong><small class="pcc-subline">#<?php echo (int)$r['user_id'];?></small></span></div></td><td><strong><?php echo $h(trim($r['first_name'].' '.$r['last_name']));?></strong></td><td><code><?php echo $h($r['citizen_id']);?></code></td><td><?php echo $h($r['birth_date']);?></td><td><?php echo $h($r['gender']??'—');?></td><td><?php echo $h($r['nationality']);?></td><td><?php echo (int)$r['reputation'];?></td><td><?php echo $h($PCC->formatDate($r['created_at']));?></td><td><span class="pcc-badge <?php echo (int)$r['online']===1?'success':'';?>"><?php echo (int)$r['online']===1?'EN LIGNE':'HORS LIGNE';?></span></td><td><a class="pcc-button small secondary" href="<?php echo URL;?>/admin.php?page=player&id=<?php echo (int)$r['user_id'];?>&tab=character">Ouvrir</a></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="pcc-alert info"><i class="fas fa-fingerprint"></i><div><strong>Citizen ID protégé</strong><p>Le Control Center ne propose aucune modification libre de <code>citizen_id</code>. Il reste généré par CharacterService lors de la création d’identité.</p></div></section>
